import json, os, sys, urllib.request, urllib.error
endpoint, query = sys.argv[1], sys.argv[2]
headers = {'Content-Type': 'application/json'}
if os.environ.get('PN_TOKEN'):
    headers['Authorization'] = 'Bearer ' + os.environ['PN_TOKEN']
request = urllib.request.Request('http://localhost:3000/' + endpoint, data=json.dumps({'query': query}).encode(), headers=headers)
try:
    print(urllib.request.urlopen(request).read().decode())
except urllib.error.HTTPError as error:
    print(error.code, error.read().decode())
